result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/gamevm/vm.py", "content": """"A tiny stack-based bytecode VM for game scripting.

Pipeline:  assembly text --assemble()--> bytecode --run()--> effects
                             ^--- disassemble() ---/
"""
from __future__ import annotations

import re
from enum import Enum
from typing import Callable, Dict, List, Sequence, Tuple, Union

# --------------------------------------------------------------------------
# Opcodes
# --------------------------------------------------------------------------

class Op(Enum):
    PUSH = "PUSH"          # PUSH imm        -> push immediate
    ADD = "ADD"            # pop b, pop a    -> push a + b
    SUB = "SUB"            # pop b, pop a    -> push a - b
    MUL = "MUL"            # pop b, pop a    -> push a * b
    CMP_LT = "CMP_LT"      # pop b, pop a    -> push 1 if a < b else 0
    JMP = "JMP"            # JMP target      -> unconditional jump
    JMPF = "JMPF"          # JMPF target     -> pop cond; jump if falsy
    LOAD = "LOAD"          # LOAD var        -> push variable value
    STORE = "STORE"        # STORE var       -> pop into variable
    CALL_HOST = "CALL_HOST"  # CALL_HOST name nargs; args pushed left-to-right;
                           # return value (possibly None) is pushed.
    HALT = "HALT"


# operand kinds per opcode: None, int immediate, jump target, var name,
# (host name, argc)
OperandKind = {
    Op.PUSH: "imm",
    Op.ADD: None, Op.SUB: None, Op.MUL: None, Op.CMP_LT: None,
    Op.JMP: "target", Op.JMPF: "target",
    Op.LOAD: "var", Op.STORE: "var",
    Op.CALL_HOST: "host",
    Op.HALT: None,
}

Instruction = Tuple[Op, Union[int, str, Tuple[str, int], None]]


class AsmError(Exception):
    """Raised for malformed assembly source."""


class VMError(Exception):
    """Base class for runtime VM errors."""


class FuelExhausted(VMError):
    """Raised when the script exceeds its instruction budget."""


class HostError(VMError):
    """Raised when CALL_HOST references an unknown host function."""


# --------------------------------------------------------------------------
# Assembler
# --------------------------------------------------------------------------

_LABEL_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*):(.*)$")


def _tokenize_line(line: str, lineno: int):
    """Strip comments/whitespace; yield (label_or_None, mnemonic, operands)."""
    line = line.split("#", 1)[0].strip()
    if not line:
        return None, None, []
    label = None
    m = _LABEL_RE.match(line)
    if m:
        label, rest = m.group(1), m.group(2).strip()
        if not rest:
            return label, None, []
        line = rest
    parts = line.split()
    return label, parts[0].upper(), parts[1:]


def assemble(src: str) -> List[Instruction]:
    """Two-pass assembler: resolve labels, emit (Op, operand) instructions."""
    # Pass 1: collect labels and parsed lines.
    lines: List[Tuple[int, str, list]] = []   # (lineno, mnemonic, operands)
    labels: Dict[str, int] = {}
    for lineno, raw in enumerate(src.splitlines(), 1):
        try:
            label, mnemonic, operands = _tokenize_line(raw, lineno)
        except Exception as exc:  # pragma: no cover
            raise AsmError(f"line {lineno}: parse error: {exc}") from exc
        if label is not None:
            if label in labels:
                raise AsmError(f"line {lineno}: duplicate label '{label}'")
            labels[label] = len(lines)
        if mnemonic is None:
            continue
        lines.append((lineno, mnemonic, operands))

    def resolve_target(name: str, lineno: int) -> int:
        if name not in labels:
            raise AsmError(f"line {lineno}: unknown label '{name}'")
        return labels[name]

    # Pass 2: encode.
    code: List[Instruction] = []
    for lineno, mnemonic, operands in lines:
        try:
            op = Op(mnemonic)
        except ValueError:
            raise AsmError(f"line {lineno}: unknown mnemonic '{mnemonic}'")
        kind = OperandKind[op]
        want = 0 if kind is None else 2 if kind == "host" else 1
        if len(operands) != want:
            raise AsmError(
                f"line {lineno}: {mnemonic} expects {want} operand(s), "
                f"got {len(operands)}")
        if kind is None:
            code.append((op, None))
        elif kind == "imm":
            try:
                code.append((op, int(operands[0], 0)))
            except ValueError:
                raise AsmError(f"line {lineno}: bad integer '{operands[0]}'")
        elif kind == "target":
            code.append((op, resolve_target(operands[0], lineno)))
        elif kind == "var":
            code.append((op, operands[0]))
        else:  # host
            try:
                nargs = int(operands[1], 0)
            except ValueError:
                raise AsmError(f"line {lineno}: bad arity '{operands[1]}'")
            if nargs < 0:
                raise AsmError(f"line {lineno}: negative arity")
            code.append((op, (operands[0], nargs)))
    return code


# --------------------------------------------------------------------------
# Disassembler
# --------------------------------------------------------------------------

def disassemble(code: Sequence[Instruction]) -> str:
    """Render bytecode back to normalized assembly text.

    Every jump target gets a synthetic label `L<index>:` so the output is
    directly re-assemblable. Comments and original label names are not
    preserved (that is what normalization means here).
    """
    targets = sorted({ins[1] for ins in code
                      if ins[0] in (Op.JMP, Op.JMPF)})
    out: List[str] = []
    for i, ins in enumerate(code):
        if i in targets:
            out.append(f"L{i}:")
        op, arg = ins
        if op in (Op.JMP, Op.JMPF):
            out.append(f"{op.value} L{arg}")
        elif op is Op.CALL_HOST:
            name, nargs = arg  # type: ignore[misc]
            out.append(f"{op.value} {name} {nargs}")
        elif OperandKind[op] is None:
            out.append(op.value)
        else:
            out.append(f"{op.value} {arg}")
    return "\n".join(out) + ("\n" if out else "")


def normalize_asm(src: str) -> str:
    """Normalize user-written asm: strip comments/blanks, canonical spacing.

    Labels are re-emitted as synthetic L<n> labels exactly like disassemble,
    so normalize_asm(user_src) == disassemble(assemble(user_src)).
    """
    return disassemble(assemble(src))


# --------------------------------------------------------------------------
# Virtual machine
# --------------------------------------------------------------------------

HostFn = Callable[..., object]


def run(code: Sequence[Instruction],
        host: Dict[str, HostFn],
        fuel: int = 100_000) -> Dict[str, object]:
    """Execute bytecode. Returns the final variable environment.

    Raises FuelExhausted if more than `fuel` instructions execute,
    or HostError on an unknown host function.
    """
    stack: List[object] = []
    env: Dict[str, object] = {}
    pc = 0
    n = len(code)

    while True:
        if pc < 0 or pc >= n:
            raise VMError(f"pc {pc} out of range (missing HALT?)")
        op, arg = code[pc]
        fuel -= 1
        if fuel < 0:
            raise FuelExhausted(
                f"script exceeded its instruction budget ({pc=} {op=})")
        pc += 1

        if op is Op.PUSH:
            stack.append(arg)
        elif op is Op.ADD:
            b, a = stack.pop(), stack.pop()
            stack.append(a + b)
        elif op is Op.SUB:
            b, a = stack.pop(), stack.pop()
            stack.append(a - b)
        elif op is Op.MUL:
            b, a = stack.pop(), stack.pop()
            stack.append(a * b)
        elif op is Op.CMP_LT:
            b, a = stack.pop(), stack.pop()
            stack.append(1 if a < b else 0)
        elif op is Op.JMP:
            pc = arg  # type: ignore[assignment]
        elif op is Op.JMPF:
            if not stack.pop():
                pc = arg  # type: ignore[assignment]
        elif op is Op.LOAD:
            stack.append(env.get(arg))
        elif op is Op.STORE:
            env[arg] = stack.pop()
        elif op is Op.CALL_HOST:
            name, nargs = arg  # type: ignore[misc]
            fn = host.get(name)
            if fn is None:
                raise HostError(f"unknown host function '{name}'")
            args = [stack.pop() for _ in range(nargs)][::-1]
            stack.append(fn(*args))
        elif op is Op.HALT:
            return env
        else:  # pragma: no cover
            raise VMError(f"unhandled opcode {op}")
